INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c96a-7fa4-a22d-57c08e185844'::uuid, '019f9df7-a2a2-7941-9e48-3d4dda1f252c'::uuid, 'A school has 36 students. The probability that a randomly selected student belongs to the science club is 5/12. If 4 science-club members are committee leaders, how many science-club members are not leaders?', '11', 'Number of science-club members = (5/12) × 36 = 15. Non-leaders = 15 - 4 = 11.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.234Z'::timestamptz, '2026-08-15T07:50:40.234Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c975-720c-988f-5711c5a08a76'::uuid, '019f9df7-a2a2-7941-9e48-3d4dda1f252c'::uuid, 'A bag contains 6 red counters, 5 blue counters and 9 green counters. Two counters are selected without replacement. Find the probability that both counters are red.', '3/38', 'Total counters = 20. P(both red) = (6/20) × (5/19) = 30/380 = 3/38.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.244Z'::timestamptz, '2026-08-15T07:50:40.244Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c97e-7ead-a93a-c7decf743b02'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'A town’s population is 6,240,000 and its land area is 780 km². Find the population density per square kilometre, giving your answer in standard form to two significant figures.', '8.0 × 10³ people per km²', 'Population density = 6,240,000 ÷ 780 = 8000 people per km² = 8.0 × 10³ people per km².', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.254Z'::timestamptz, '2026-08-15T07:50:40.254Z'::timestamptz) ON CONFLICT (id) DO NOTHING;